import React from 'react';
import { ChatPanel } from './ChatPanel';
import { NotesPanel } from './NotesPanel';
import { ParticipantsPanel } from './ParticipantsPanel';
import { WhiteboardPanel } from './WhiteboardPanel'; // ✅ IMPORT

export const SidePanel = ({ 
  activePanel, 
  setActivePanel, 
  messages, 
  onSendMessage, 
  participants, 
  roomId,
  // ✅ REMOVED: onPlayAudio prop removed
  onPlayAnimation 
}) => {
  const [inputText, setInputText] = useState('');
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = (e) => {
    e.preventDefault();
    if (inputText.trim()) {
      onSendMessage(inputText);
      setInputText('');
    }
  };

  return (
    <div className="w-96 bg-slate-900/95 backdrop-blur-lg border-l border-purple-500/20 flex flex-col">
      {/* Tabs */}
      <div className="flex border-b border-purple-500/20">
        <button
          onClick={() => setActivePanel('chat')}
          className={`flex-1 py-3 font-medium transition-all ${
            activePanel === 'chat'
              ? 'bg-purple-600/20 text-purple-300 border-b-2 border-purple-500'
              : 'text-gray-400 hover:text-purple-300'
          }`}
        >
          💬 Chat
        </button>
        <button
          onClick={() => setActivePanel('participants')}
          className={`flex-1 py-3 font-medium transition-all ${
            activePanel === 'participants'
              ? 'bg-purple-600/20 text-purple-300 border-b-2 border-purple-500'
              : 'text-gray-400 hover:text-purple-300'
          }`}
        >
          👥 Participants ({participants.length})
        </button>
      </div>

      {/* Content */}
      {activePanel === 'chat' ? (
        <div className="flex-1 flex flex-col">
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {messages.map((msg, idx) => (
              <div
                key={idx}
                className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[80%] px-4 py-3 rounded-2xl ${
                    msg.sender === 'user'
                      ? 'bg-purple-600 text-white'
                      : 'bg-slate-800 text-gray-100 border border-purple-500/30'
                  }`}
                >
                  <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</p>
                  {/* ✅ REMOVED: Play button completely removed - no more replay option */}
                </div>
              </div>
            ))}
            <div ref={messagesEndRef} />
          </div>

          <form onSubmit={handleSend} className="p-4 border-t border-purple-500/20">
            <div className="flex space-x-2">
              <input
                type="text"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                placeholder="Type a message..."
                className="flex-1 px-4 py-2 bg-slate-800 border border-purple-500/30 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-purple-500"
              />
              <button
                type="submit"
                className="px-6 py-2 bg-purple-600 hover:bg-purple-700 rounded-lg font-medium transition-all"
              >
                Send
              </button>
            </div>
          </form>
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto p-4 space-y-2">
          {participants.map((participant, idx) => (
            <div
              key={idx}
              className="flex items-center space-x-3 px-4 py-3 bg-slate-800/50 rounded-lg border border-purple-500/20"
            >
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center font-bold">
                {participant.userId.substring(0, 2).toUpperCase()}
              </div>
              <div className="flex-1">
                <p className="font-medium text-gray-100">{participant.userId.substring(0, 20)}...</p>
                <p className="text-xs text-gray-400">Active</p>
              </div>
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default SidePanel;
